src = r'''
import hou, math
AC = "/obj/anim_ctrl"
FPS = 24.0
EYE = hou.Vector3(0.0, 0.975, 0.02)

def _f():
    return hou.frame()

def acv(name, f):
    return hou.node(AC).parm(name).evalAtFrame(f)

def hc_xform(f):
    return hou.node("/obj/hand_contact").worldTransformAtTime(hou.frameToTime(f))

def bob(f):
    w = acv("bob_weight", f)
    if w == 0.0:
        return 0.0
    a = acv("bob_amp", f)
    # low amplitude vertical bobbing: sum of two sines (pseudo-noise)
    return w * a * (0.75 * math.sin(2*math.pi*1.3*f/FPS) + 0.25 * math.sin(2*math.pi*3.1*f/FPS + 1.1))

def world_path(f):
    return hou.Vector3(acv("path_tx", f), acv("path_ty", f), acv("path_tz", f))

def hand_point(f, m=None):
    if m is None:
        m = hc_xform(f)
    off = hou.Vector3(acv("hand_offx", f), acv("hand_offy", f), acv("hand_offz", f))
    return off * m

def body_pos(f):
    w = acv("attach_blend", f)
    p = world_path(f)
    if w > 0.0:
        p = p * (1.0 - w) + hand_point(f) * w
    return p + hou.Vector3(0.0, bob(f), 0.0)

def _yaw_of(v):
    return math.degrees(math.atan2(v[0], v[2]))

def flight_rot(f):
    d = 2.0
    v = (body_pos(f + d) - body_pos(f - d)) * (FPS / (2*d))      # m/s
    hz = hou.Vector3(0, 0, 1) * hc_xform(f).extractRotationMatrix3()
    hz = hou.Vector3(hz[0], 0.0, hz[2])
    if hz.length() > 1e-6:
        hz = hz.normalized()
    vh = hou.Vector3(v[0], 0.0, v[2])
    dirh = vh + hz * 0.08
    yaw = _yaw_of(dirh)
    pitch = -math.degrees(math.atan2(v[1], max(vh.length(), 0.05))) * 0.5
    pitch = max(-25.0, min(25.0, pitch))
    return hou.hmath.buildRotate(hou.Vector3(pitch, yaw, 0.0), "xyz").extractRotationMatrix3()

def _wrap(a):
    while a > 180.0: a -= 360.0
    while a <= -180.0: a += 360.0
    return a

def euler_xyz(m3):
    m4 = hou.Matrix4(m3)
    r = m4.extractRotates("srt", "xyz")
    fwd = hou.Vector3(0, 0, 1) * m3
    hint = _yaw_of(hou.Vector3(fwd[0], 0.0, fwd[2]))
    a = (r[0], r[1], r[2])
    b = (_wrap(r[0] + 180.0), _wrap(180.0 - r[1]), _wrap(r[2] + 180.0))
    def dist(e):
        return abs(_wrap(e[1] - hint))
    return a if dist(a) <= dist(b) else b

def body_rot(f):
    rw = acv("rot_blend", f)
    if rw >= 1.0:
        m = hc_xform(f).extractRotationMatrix3()
    elif rw <= 0.0:
        m = flight_rot(f)
    else:
        q0 = hou.Quaternion(flight_rot(f))
        q1 = hou.Quaternion(hc_xform(f).extractRotationMatrix3())
        m = q0.slerp(q1, rw).extractRotationMatrix3()
    return euler_xyz(m)

def body_t(i):
    return body_pos(_f())[i]

def body_r(i):
    return body_rot(_f())[i]

def flap_phase(f):
    # integral of frequency (Hz) over time -> cycles; keeps phase continuous while frequency is keyed
    p = hou.node(AC).parm("flap_freq")
    fi = int(math.floor(f))
    s = 0.0
    for k in range(1, fi):
        s += 0.5 * (p.evalAtFrame(k) + p.evalAtFrame(k + 1)) / FPS
    s += (f - fi) * p.evalAtFrame(f) / FPS
    return s

def flap_value(f):
    mode = acv("flap_mode", f)
    v = 0.0
    if mode > 0.0:
        v += mode * (acv("flap_offset", f) + acv("flap_amp", f) * math.sin(2*math.pi*flap_phase(f)))
    if mode < 1.0:
        v += (1.0 - mode) * acv("flap_keyed", f)
    lo = acv("flap_min", f); hi = acv("flap_max", f)
    return max(lo, min(hi, v))

def flap():
    return flap_value(_f())

def head_look(f):
    lag = acv("look_lag", f)
    tgt = hou.node("/obj/butterfly/CTRL_body").worldTransformAtTime(hou.frameToTime(f - lag)).extractTranslates()
    d = tgt - EYE
    yaw = math.degrees(math.atan2(d[0], d[2]))
    pitch = -math.degrees(math.atan2(d[1], math.hypot(d[0], d[2])))
    return (max(-35.0, min(40.0, pitch)), max(-70.0, min(70.0, yaw)))

def head_rx():
    f = _f(); w = acv("look_weight", f)
    base = acv("head_base_rx", f)
    return base if w <= 0 else base * (1 - w) + head_look(f)[0] * w

def head_ry():
    f = _f(); w = acv("look_weight", f)
    base = acv("head_base_ry", f)
    return base if w <= 0 else base * (1 - w) + head_look(f)[1] * w
'''
